}

.related-item .content h4,
.related-item .content h4 a,
.related-item .content h4 a:link,
.related-item .content h4 a:visited,
.sidebar-related h4,
.sidebar-related h4 a,
.sidebar-related h4 a:link,
.sidebar-related h4 a:visited,
.sidebar-related .related-item h4,
.sidebar-related .related-item h4 a,
.sidebar-related .related-item h4 a:link,
.sidebar-related .related-item h4 a:visited,
.theme-crimson .related-item .content h4,
.theme-crimson .related-item .content h4 a,
