.theme-crimson .related-item .content h4 a:visited,
.theme-crimson .sidebar-related h4,
.theme-crimson .sidebar-related h4 a,
.theme-crimson .sidebar-related h4 a:link,
.theme-crimson .sidebar-related h4 a:visited,
.theme-crimson .sidebar-related .related-item h4,
.theme-crimson .sidebar-related .related-item h4 a,
.theme-crimson .sidebar-related .related-item h4 a:link,
.theme-crimson .sidebar-related .related-item h4 a:visited {
