}

.related-item .content h4 a:hover,
.sidebar-related h4 a:hover,
.sidebar-related .related-item h4 a:hover,
.theme-crimson .related-item .content h4 a:hover,
.theme-crimson .sidebar-related h4 a:hover,
.theme-crimson .sidebar-related .related-item h4 a:hover {
  color: var(--primary) !important;
  text-decoration: underline !important;
}

.related-item .content p,
.theme-crimson .related-item .content p {
  font-size: 0.8rem !important;
  color: #4b5563 !important;
  margin-bottom: 6px !important;
  line-height: 1.45 !important;
}

.related-item .readmore,
.theme-crimson .related-item .readmore {
  font-size: 0.8rem !important;
  font-weight: 800 !important;
  color: var(--primary) !important;
  display: inline-flex !important;
  align-items: center !important;
  gap: 4px !important;
}

/* Sidebar Promo Box (Light Luxury Card with Crisp Black Text) */
.sidebar-hero,
.article-sidebar .sidebar-hero,
.sidebar-hero.sidebar-hero-light {
  background: #ffffff !important;
