  box-shadow: 0 6px 20px rgba(234, 88, 12, 0.5) !important;
  background: linear-gradient(135deg, #fbbf24 0%, #f97316 100%) !important;
  color: #ffffff !important;
}

/* ==========================================================================
   PREMIUM CONSULTATION WIDGET (KONSULTASI GRATIS)
   ========================================================================== */
.consultation-widget {
  background: linear-gradient(180deg, #ffffff 0%, #f0fdf4 100%) !important;
  border: 1px solid #bbf7d0 !important;
  border-radius: 16px !important;
  padding: 22px !important;
  box-shadow: 0 6px 22px rgba(22, 163, 74, 0.08) !important;
  position: relative !important;
  transition: transform 0.25s ease, box-shadow 0.25s ease !important;
}

.consultation-widget:hover {
  transform: translateY(-3px) !important;
  box-shadow: 0 10px 28px rgba(22, 163, 74, 0.15) !important;
}

.consult-header {
  display: flex !important;
  align-items: center !important;
  justify-content: space-between !important;
  margin-bottom: 14px !important;
}

.consult-badge {
  display: inline-flex !important;
  align-items: center !important;
  gap: 6px !important;
  background: #dcfce7 !important;
  color: #15803d !important;
  font-size: 0.74rem !important;
  font-weight: 800 !important;
  letter-spacing: 0.5px !important;
  padding: 4px 10px !important;
  border-radius: 6px !important;
  text-transform: uppercase !important;
}

.consult-online {
  display: inline-flex !important;
  align-items: center !important;
  gap: 6px !important;
  font-size: 0.72rem !important;
  font-weight: 700 !important;
  color: #16a34a !important;
}

.pulse-dot {
  width: 8px !important;
  height: 8px !important;
  border-radius: 50% !important;
  background: #22c55e !important;
  box-shadow: 0 0 0 0 rgba(34, 197, 94, 0.7) !important;
  animation: pulseGreen 1.8s infinite !important;
}

@keyframes pulseGreen {
  0% { transform: scale(0.95); box-shadow: 0 0 0 0 rgba(34, 197, 94, 0.7); }
  70% { transform: scale(1); box-shadow: 0 0 0 6px rgba(34, 197, 94, 0); }
  100% { transform: scale(0.95); box-shadow: 0 0 0 0 rgba(34, 197, 94, 0); }
}

.consultation-widget h4,
.theme-crimson .consultation-widget h4 {
  font-family: var(--font-heading) !important;
  font-size: 1.18rem !important;
  font-weight: 800 !important;
