  color: #374151 !important;
  line-height: 1.55 !important;
  margin-bottom: 14px !important;
}

.consult-features {
  list-style: none !important;
  padding: 0 !important;
  margin: 0 0 16px 0 !important;
  display: flex !important;
  flex-direction: column !important;
  gap: 7px !important;
}

.consult-features li {
  display: flex !important;
  align-items: center !important;
  gap: 8px !important;
  font-size: 0.8rem !important;
  font-weight: 700 !important;
  color: #1f2937 !important;
}

.consult-features li i {
  color: #16a34a !important;
  font-size: 0.9rem !important;
  flex-shrink: 0 !important;
}

.btn-consult-wa {
  display: flex !important;
  align-items: center !important;
  justify-content: center !important;
  gap: 9px !important;
  width: 100% !important;
  background: linear-gradient(135deg, #25d366 0%, #16a34a 100%) !important;
  color: #ffffff !important;
  font-weight: 800 !important;
  font-size: 0.92rem !important;
  padding: 12px 18px !important;
  border-radius: 12px !important;
  text-decoration: none !important;
  box-shadow: 0 4px 16px rgba(37, 211, 102, 0.35) !important;
  transition: all 0.25s ease !important;
}

.btn-consult-wa:hover {
  transform: translateY(-2px) scale(1.02) !important;
  box-shadow: 0 8px 24px rgba(37, 211, 102, 0.5) !important;
  color: #ffffff !important;
  background: linear-gradient(135deg, #22c55e 0%, #15803d 100%) !important;
}

.btn-consult-wa i {
  font-size: 1.25rem !important;
}

.consult-guarantee {
  margin-top: 10px !important;
  text-align: center !important;
  font-size: 0.74rem !important;
  color: #6b7280 !important;
  font-weight: 600 !important;
}

.btn-cta-wa {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 8px;
  width: 100%;
  padding: 11px;
  border-radius: 8px;
  font-weight: 700;
  font-size: 0.9rem;
  transition: var(--transition);
}

/* News Widget / Video Highlight */
.news-widget {
  background: #ffffff;
  border: 1px solid var(--border-light);
  border-radius: 14px;
  padding: 18px;
  box-shadow: 0 4px 14px rgba(0, 0, 0, 0.03);
}

.news-widget-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  margin-bottom: 12px;
}

.news-widget-badge {
  background: #fee2e2;
  color: var(--primary);
  font-size: 0.72rem;
  font-weight: 800;
  padding: 3px 8px;
  border-radius: 4px;
}

.news-widget-tag {
  font-size: 0.72rem;
  font-weight: 700;
  color: #6b7280;
}

.news-widget-video-wrap {
  position: relative;
  border-radius: 10px;
  overflow: hidden;
  aspect-ratio: 16 / 9;
  background: #000000;
  margin-bottom: 12px;
}

.news-widget-video-thumb {
  width: 100%;
  height: 100%;
  object-fit: cover;
}

.news-widget-video-overlay {
  position: absolute;
  inset: 0;
  background: rgba(0, 0, 0, 0.3);
}

.news-widget-video-play {
  position: absolute;
  top: 50%;
  left: 50%;
  transform: translate(-50%, -50%);
  width: 48px;
  height: 48px;
  border-radius: 50%;
  background: rgba(255, 255, 255, 0.9);
  color: var(--primary);
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 1.15rem;
  box-shadow: 0 4px 14px rgba(0, 0, 0, 0.3);
  transition: var(--transition);
}

.news-widget:hover .news-widget-video-play {
  transform: translate(-50%, -50%) scale(1.1);
  background: #ffffff;
}

.news-widget-video-duration {
  position: absolute;
  bottom: 8px;
  right: 8px;
  background: rgba(0, 0, 0, 0.75);
  color: #ffffff;
  font-size: 0.72rem;
  font-weight: 700;
  padding: 2px 6px;
  border-radius: 4px;
}

.news-widget-video-title {
  font-size: 0.94rem;
  font-weight: 700;
  color: var(--text-dark);
  line-height: 1.35;
  margin-bottom: 6px;
}

.news-widget-video-desc {
  font-size: 0.8rem;
  color: #6b7280;
  line-height: 1.45;
  margin-bottom: 10px;
}

.news-widget-action {
  font-size: 0.82rem;
  font-weight: 700;
  color: var(--primary);
}

/* ==========================================================================
   RECOMMENDED PACKAGES STRIP
   ========================================================================== */
.grid-240 {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 24px;
}

@media (max-width: 850px) {
  .grid-240 {
    grid-template-columns: 1fr;
  }
}

.recommend-item {
  background: #ffffff;
  border: 1px solid #e5e7eb;
  border-radius: 14px;
  overflow: hidden;
  box-shadow: 0 4px 14px rgba(0, 0, 0, 0.04);
  transition: var(--transition);
}

.recommend-item:hover {
  transform: translateY(-4px);
  box-shadow: 0 10px 24px rgba(0, 0, 0, 0.08);
}

.recommend-item .thumb {
  height: 180px;
  overflow: hidden;
}

.recommend-item .thumb img {
  width: 100%;
  height: 100%;
  object-fit: cover;
  transition: transform 0.4s ease;
}

.recommend-item:hover .thumb img {
  transform: scale(1.06);
}

.recommend-item .body {
  padding: 20px;
}

.prod-cat-label {
  font-size: 0.74rem;
  font-weight: 800;
  color: var(--primary);
  text-transform: uppercase;
  margin-bottom: 6px;
  display: block;
}

.recommend-item h4 {
  font-size: 1.1rem;
  font-weight: 800;
  color: var(--text-dark);
  margin-bottom: 8px;
  line-height: 1.3;
}

.recommend-item p {
  font-size: 0.85rem;
  color: #4b5563;
  margin-bottom: 14px;
  line-height: 1.5;
}

.prod-card-link-auto {
  font-size: 0.85rem;
  font-weight: 700;
  color: var(--primary);
  display: inline-flex;
  align-items: center;
  gap: 4px;
}

/* ==========================================================================
   FOOTER (MATCHING USER TEMPLATE & PRD 5.3)
   ========================================================================== */
.footer {
