/* ==========================================================================
   FLOATING BUTTONS (WHATSAPP & BACK TO TOP)
   ========================================================================== */
.floating-wa {
  position: fixed;
  bottom: 24px;
  right: 24px;
  z-index: 1020;
  display: flex;
  align-items: center;
}

.floating-wa-tooltip {
  background: #ffffff;
  color: #1f2937;
  font-size: 0.82rem;
  font-weight: 700;
  padding: 6px 14px;
  border-radius: var(--radius-full);
  box-shadow: 0 4px 16px rgba(0, 0, 0, 0.15);
  margin-right: 10px;
  white-space: nowrap;
  opacity: 0;
  visibility: hidden;
  pointer-events: none;
  transform: translateX(8px) scale(0.96);
  transition: opacity 0.22s cubic-bezier(0.4, 0, 0.2, 1), transform 0.22s cubic-bezier(0.4, 0, 0.2, 1), visibility 0.22s;
}

.floating-wa:hover .floating-wa-tooltip,
.floating-wa:focus-within .floating-wa-tooltip {
  opacity: 1;
  visibility: visible;
  pointer-events: auto;
  transform: translateX(0) scale(1);
}

.floating-wa-btn {
  width: 56px;
  height: 56px;
  border-radius: 50%;
  background: linear-gradient(135deg, #25d366, #128c7e);
  color: #ffffff;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 1.65rem;
  box-shadow: 0 8px 24px rgba(37, 211, 102, 0.45);
  transition: var(--transition);
}

.floating-wa-btn:hover {
  transform: scale(1.08) translateY(-2px);
  box-shadow: 0 12px 30px rgba(37, 211, 102, 0.6);
  color: #ffffff;
}

#backToTop {
  position: fixed !important;
  bottom: 94px !important;
  right: 28px !important;
  z-index: 1035 !important;
  width: 44px !important;
  height: 44px !important;
  border-radius: 50% !important;
  background: rgba(30, 2, 2, 0.92) !important;
  backdrop-filter: blur(8px) !important;
  border: 1px solid rgba(255, 255, 255, 0.28) !important;
  color: #ffffff !important;
  display: flex !important;
  align-items: center !important;
  justify-content: center !important;
  font-size: 1rem !important;
  cursor: pointer !important;
  opacity: 0 !important;
  visibility: hidden !important;
  pointer-events: none !important;
  transition: opacity 0.25s ease, visibility 0.25s ease, transform 0.25s ease, background 0.25s ease !important;
  box-shadow: 0 4px 16px rgba(0, 0, 0, 0.35) !important;
}

#backToTop.show {
  opacity: 1 !important;
  visibility: visible !important;
  pointer-events: auto !important;
}

#backToTop:hover {
  background: var(--primary) !important;
  transform: translateY(-3px) scale(1.05) !important;
  color: #ffffff !important;
}

